public final class VideoFacade {
    private final VideoDecoder decoder;
    private final FilterEngine filters;
    private final Encoder encoder;
    private final TempStore temps;

    public VideoFacade(VideoDecoder decoder, FilterEngine filters,
                       Encoder encoder, TempStore temps) {
        this.decoder = decoder;
        this.filters = filters;
        this.encoder = encoder;
        this.temps = temps;
    }

    // The only method 90% of callers need. Owns order + cleanup + translation.
    public String encode(String source, String format) {
        if (source == null || source.isBlank()) throw new BadRequestException("source required");
        if (format == null) format = "mp4"; // default lives here, not in 20 callers
        TempStore.Handle h = temps.alloc();
        try {
            Frames frames = decoder.decode(source, h);
            Frames cut = filters.apply(frames);
            return encoder.encode(cut, format, h);
        } catch (SubsystemException e) {
            // Translate, do not erase: preserve step + retryability.
            throw new EncodingFailedException(e.step(), e.getMessage(), e.isRetryable(), e);
        } finally {
            temps.release(h); // client can never forget this again
        }
    }

    // Escape hatch: power users keep direct access. Facade does not forbid it.
    public VideoDecoder rawDecoder() { return decoder; }
}

